const GUEST_SESSION_KEY='jokers-guest-session';
let memoryGuestSessionToken='';
function getGuestSessionToken(){try{const saved=sessionStorage.getItem(GUEST_SESSION_KEY);if(saved)return saved}catch{}return memoryGuestSessionToken}
function setGuestSessionToken(token){memoryGuestSessionToken=token||'';try{if(token)sessionStorage.setItem(GUEST_SESSION_KEY,token);else sessionStorage.removeItem(GUEST_SESSION_KEY)}catch{}}
function guestAuthHeaders(){const token=getGuestSessionToken();return token?{Authorization:`Bearer ${token}`}:{}}
const API = async (url, options={}) => {
  const config={method:options.method||'GET',credentials:'include',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...guestAuthHeaders(),...(options.headers||{})}};
  if(options.body) config.body=JSON.stringify(options.body);
  const response=await fetch(url,config);
  let data={}; try{data=await response.json()}catch{}
  if(!response.ok){const error=new Error(data.error||`Erro ${response.status}`);error.status=response.status;throw error}
  return data;
};
