function initials(user){return (user?.full_name||'CA').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'CA'}
function money(value){if(value===null||value===undefined||value==='')return '—';return Number(value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function dateLabel(value){if(!value)return 'Agora';const d=new Date(value);if(Number.isNaN(d.valueOf()))return '';return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
function dateISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function textOr(value, fallback='Informação não fornecida.'){return value===null||value===undefined||String(value).trim()===''?fallback:String(value)}
function jsonText(value){return Array.isArray(value)?value.join('\n'):String(value??'')}
function showToast(message,type='success'){const root=$('#toast-stack');if(!root)return;const node=document.createElement('div');node.className=`toast ${type}`;node.innerHTML=`<span class="toast-dot"></span><span>${esc(message)}</span>`;root.appendChild(node);setTimeout(()=>node.remove(),4200)}
function setBusy(button,on,label){if(!button)return;button.disabled=on;if(on){button.dataset.original=button.innerHTML;button.innerHTML=`<span class="spinner" style="width:13px;height:13px"></span>${esc(label||'Salvando…')}`}else if(button.dataset.original){button.innerHTML=button.dataset.original;delete button.dataset.original}}
