function analysisString(value){if(value==null)return '';if(Array.isArray(value))return value.map(x=>typeof x==='object'?`${x.text||''} | ${x.url||''}`:String(x)).join('\n');if(typeof value==='object')return JSON.stringify(value);return String(value)}
