async function completeLogin(data){if(data.user?.is_guest&&data.session_token)setGuestSessionToken(data.session_token);else if(!data.user?.is_guest)setGuestSessionToken('');state.user=data.user;state.authMode='login';state.authAlert='';state.policyResult=null;state.policyText='';state.learningData=null;state.agentRun=null;state.agentBrief=null;state.agentDiagnosis=null;state.agentDraft=null;state.agentInputValues=null;state.agentAnalysis=null;state.agentHistory=null;state.agentDashboard=null;state.agentFeedback=null;state.agentPolicyResult=null;state.agentSimulation=null;state.agentApprovalResult=null;state.page='dashboard';await refreshCore({withDashboard:true})}
async function handleSubmit(event){const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const kind=form.dataset.form;const values=fieldValues(form);const button=$('button[type="submit"]',form);setBusy(button,true,'Enviando…');try{
if(kind==='auth-login'){const result=await API('/api/auth/login',{method:'POST',body:values});await completeLogin(result);return}
if(kind==='auth-register'){const result=await API('/api/auth/register',{method:'POST',body:values});await completeLogin(result);showToast('Conta criada. Bem-vindo ao workspace.');return}
if(kind==='auth-forgot'){const result=await API('/api/auth/forgot-password',{method:'POST',body:values});if(result.reset_token){state.resetToken=result.reset_token;state.authAlert=`${result.message} Token local de demonstração: ${result.reset_token}`;state.authMode='reset'}else{state.authAlert=result.message;state.authMode='forgot'}render();return}
if(kind==='auth-reset'){const result=await API('/api/auth/reset-password',{method:'POST',body:values});state.resetToken='';state.authAlert=result.message;state.authMode='login';render();return}
if(kind==='agent-interpret'){const raw=agentFormValues(form);state.agentInputValues=raw;state.agentWorkflowMode=raw.workflow_mode||state.agentWorkflowMode;const body=makeAgentPayload(raw);if(body.source==='url'&&(!state.agentAnalysis||String(state.agentAnalysis.source_url||'')!==String(body.url||''))){const analysis=await API('/api/analyze-url',{method:'POST',body:{url:body.url}});state.agentAnalysis=analysis.analysis;state.agentInputValues=applyAgentAnalysisValues(raw,analysis.analysis);state.agentScreen='input';render();showToast('Página analisada. Revise/corrija todos os campos antes de interpretar o briefing.');return}body.page_analysis=body.source==='url'?state.agentAnalysis:null;const result=await API('/api/agent/brief',{method:'POST',body});state.agentDraft=body;state.agentBrief=result.brief;state.agentDiagnosis=result.diagnosis;state.agentProductPreview=result.product_preview;state.agentScreen='confirm';render();return}
if(kind==='agent-simulation'){const scenarios=[values.cpa_1,values.cpa_2,values.cpa_3].filter(value=>value!==undefined&&String(value).trim()!=='');const result=await API('/api/agent/simulate',{method:'POST',body:{run_id:state.agentRun.id,daily_budget:values.daily_budget,days:values.days,price:values.price,cpa_scenarios:scenarios}});state.agentSimulation=result.simulation;render();return}
if(kind==='agent-chat'){const result=await API(`/api/agent/runs/${encodeURIComponent(state.agentRun.id)}/chat`,{method:'POST',body:{message:values.message}});state.agentRun.messages=result.messages;render();return}
if(kind==='agent-approval'){if(values.confirm_no_publish!=='on')throw new Error('Marque a confirmação explícita antes de aprovar para configuração manual.');const result=await API(`/api/projects/${encodeURIComponent(state.project.id)}/approve`,{method:'POST',body:{explicit_confirmation:true}});state.agentApprovalResult=result;state.agentPolicyResult=result.review;state.project=result.project;state.agentRun.project=result.project;render();showToast(result.approved?'Aprovação interna concluída. Nenhum anúncio foi publicado.':`Revisão pendente: ${(result.missing||[]).length} item(ns).` ,result.approved?'success':'error');return}
if(kind==='analyze-url'){const result=await API('/api/analyze-url',{method:'POST',body:values});state.urlAnalysis=result.analysis;state.urlEditing=false;renderURLReviewModal();return}
if(kind==='url-confirm'){const analysis=state.urlAnalysis;if(!analysis)throw new Error('A análise da página expirou. Comece novamente.');if(!String(values.name||'').trim())throw new Error('Informe o nome do produto antes de continuar.');const mode=state.campaignMode;const productResult=await API('/api/products',{method:'POST',body:{...values,page_analysis:analysis}});const projectName=`Campanha — ${productResult.product.name}`.slice(0,160);const projectResult=await API('/api/projects',{method:'POST',body:{name:projectName,product_id:productResult.product.id}});state.project=projectResult.project;localStorage.setItem('cakto-active-project',projectResult.project.id);closeModal();state.page=mode==='automatic'?'pack':'wizard';state.wizardStep=0;if(mode==='automatic'){const generated=await API(`/api/projects/${encodeURIComponent(projectResult.project.id)}/automate`,{method:'POST',body:{}});state.project=generated.project;showToast('Produto confirmado. Pacote automático gerado e pronto para revisão.')}else showToast('Produto confirmado. Continue no modo avançado, etapa por etapa.');state.pendingCampaignMode=null;state.pendingProjectAfterProduct=false;await refreshCore();state.page=mode==='automatic'?'pack':'wizard';render();return}
if(kind==='product'){const id=form.dataset.id;const result=await API(id?`/api/products/${encodeURIComponent(id)}`:'/api/products',{method:id?'PUT':'POST',body:values});const startProject=!!state.pendingProjectAfterProduct;state.pendingProjectAfterProduct=false;closeModal();state.page='products';await refreshCore();showToast(id?'Produto atualizado.':'Produto cadastrado.');if(startProject)openProjectModal(result.product.id);return}
if(kind==='project-create'){const mode=state.pendingCampaignMode;const result=await API('/api/projects',{method:'POST',body:values});closeModal();state.project=result.project;state.page=mode==='automatic'?'pack':'wizard';state.wizardStep=0;localStorage.setItem('cakto-active-project',result.project.id);if(mode==='automatic'){const generated=await API(`/api/projects/${encodeURIComponent(result.project.id)}/automate`,{method:'POST',body:{}});state.project=generated.project;showToast('Produto confirmado. Pacote automático gerado para revisão.')}else showToast('Projeto criado e vinculado ao produto.');state.pendingCampaignMode=null;await refreshCore();state.page=mode==='automatic'?'pack':'wizard';render();return}
if(kind==='project-base'){const result=await API(`/api/projects/${encodeURIComponent(state.project.id)}`,{method:'PUT',body:values});state.project=result.project;state.projects=state.projects.map(p=>p.id===state.project.id?{...p,...result.project}:p);showToast('Etapa Produto salva.');render();return}
if(kind==='item-edit'){const itemKind=form.dataset.kind,id=form.dataset.id;const data={...values};if(itemKind==='offers')data.benefits=(data.benefits||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(itemKind==='angles'&&data.potential_score!=='')data.potential_score=Number(data.potential_score);await API(`/api/projects/${encodeURIComponent(state.project.id)}/items/${itemKind}/${encodeURIComponent(id)}`,{method:'PUT',body:{data}});closeModal();await refreshProject();showToast('Item atualizado.');return}
if(kind==='campaign'){if(!state.project)throw new Error('Selecione um projeto.');const body={...values,creative_id:values.creative_id||null,copy_id:values.copy_id||null};const result=await API(`/api/projects/${encodeURIComponent(state.project.id)}/campaign`,{method:'PUT',body});state.project.campaign=result.campaign;state.project.selected_creative_id=result.campaign.creative_id||null;state.project.selected_copy_id=result.campaign.copy_id||null;state.projects=state.projects.map(p=>p.id===state.project.id?{...p,...state.project}:p);showToast('Estrutura salva. Nenhuma campanha foi publicada.');render();return}
if(kind==='ads'){if(!state.project?.campaign)throw new Error('Monte a estrutura de campanha primeiro.');const current=state.project.campaign.ads||[];const ads=current.map((ad,i)=>({id:ad.id,ad_name:values[`ad_name_${i}`]||`Anúncio ${i+1}`,creative_id:values[`creative_id_${i}`]||null,copy_id:values[`copy_id_${i}`]||null,hook:values[`hook_${i}`]||'',headline:values[`headline_${i}`]||'',description:values[`description_${i}`]||'',cta:values[`cta_${i}`]||'',url:values[`url_${i}`]||state.project.campaign.url||''}));const result=await API(`/api/projects/${encodeURIComponent(state.project.id)}/campaign`,{method:'PUT',body:{ads}});state.project.campaign=result.campaign;await refreshProject();showToast(`${ads.length} anúncio(s) salvo(s).`);return}
if(kind==='metrics'){const body={...values};const result=await API(`/api/projects/${encodeURIComponent(state.project.id)}/metrics`,{method:'POST',body});await refreshProject();showToast('Registro de métricas salvo e métricas derivadas calculadas.');return}
if(kind==='test'){const id=form.dataset.id;const result=await API(`/api/projects/${encodeURIComponent(state.project.id)}/tests${id?'/'+encodeURIComponent(id):''}`,{method:id?'PUT':'POST',body:values});closeModal();await refreshProject();showToast(id?'Teste atualizado.':'Teste registrado.');return}
if(kind==='profile'){const result=await API('/api/me',{method:'PUT',body:values});state.user=result.user;await refreshCore({withDashboard:false});showToast('Perfil atualizado.');return}
if(kind==='security'){const result=await API('/api/me/security',{method:'PUT',body:values});form.reset();showToast(result.message);return}
if(kind==='policy-check'){state.policyText=values.text||'';const result=await API('/api/policy/check',{method:'POST',body:{text:state.policyText}});state.policyResult=result.review;render();showToast('Revisão interna concluída.');return}
}catch(error){if(kind.startsWith('auth-'))showAuthError(error.message);else showToast(error.message||'Não foi possível salvar.','error')}finally{if(document.contains(button))setBusy(button,false)}}
document.addEventListener('click',handleClick);
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',async event=>{const target=event.target;const agentForm=target.closest('form[data-form="agent-interpret"]');if(agentForm&&target.matches('[name="source"],[name="product_id"],[name="workflow_mode"]')){const values=agentFormValues(agentForm);const previousSource=state.agentInputValues?.source||'existing';if(target.name==='workflow_mode')state.agentWorkflowMode=target.value;if(target.name==='source'&&target.value==='manual'&&previousSource==='existing'){const existing=state.products.find(p=>p.id===values.product_id);if(existing){for(const key of ['name',...AGENT_PRODUCT_FIELDS.map(x=>x[0]),'unit_cost'])if(existing[key]!==undefined)values[key]=existing[key]??'';values.price=values.price||existing.promo_price||existing.price||'';values.has_sales_page=existing.sales_url?'yes':'no';values.has_checkout=existing.checkout_url?'yes':'no'}}if(target.name==='source'&&target.value==='url'&&previousSource!=='url'){values.price='';values.product_id='';values.url='';for(const key of ['name',...AGENT_PRODUCT_FIELDS.map(x=>x[0]),'unit_cost'])values[key]=''}if(target.name==='source'&&target.value==='existing'&&previousSource!=='existing'){const existing=state.products.find(p=>p.id===values.product_id)||state.products[0];values.product_id=existing?.id||'';values.price=existing?(existing.promo_price??existing.price??''):'';values.has_sales_page=existing?.sales_url?'yes':'no';values.has_checkout=existing?.checkout_url?'yes':'no'}if(target.name==='product_id'){const product=state.products.find(p=>p.id===target.value);values.price=product?(product.promo_price??product.price??''):'';values.has_sales_page=product?.sales_url?'yes':'no';values.has_checkout=product?.checkout_url?'yes':'no'}state.agentInputValues=values;state.agentWorkflowMode=values.workflow_mode||state.agentWorkflowMode;if(target.name==='source')state.agentAnalysis=null;render();return}const select=event.target.closest('[data-project-switch]');if(select){try{await setProject(select.value)}catch(error){showToast(error.message,'error')}return}});
document.addEventListener('input',event=>{const el=event.target;const agentForm=el.closest?.('form[data-form="agent-interpret"]');if(agentForm){state.agentInputValues=agentFormValues(agentForm);state.agentWorkflowMode=state.agentInputValues.workflow_mode||state.agentWorkflowMode;return}if(el.matches('[data-search-products]')){state.productSearch=el.value;$$('[data-product-card]').forEach(card=>{const text=card.innerText.toLowerCase();card.style.display=text.includes(el.value.toLowerCase())?'':'none'});return}if(el.matches('[data-search-projects]')){state.projectSearch=el.value;$$('.project-card').forEach(card=>{card.style.display=card.innerText.toLowerCase().includes(el.value.toLowerCase())?'':'none'});return}if(el.matches('[data-policy-text]'))state.policyText=el.value});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.modal)closeModal();if(event.key==='Escape'&&state.sidebarOpen){state.sidebarOpen=false;render()}});
async function boot(){try{const me=await API('/api/me');state.user=me.user;await refreshCore({withDashboard:true})}catch(error){state.user=null;state.authMode='login';state.authAlert='';render()}}
boot();
